import trimesh, numpy as np
h = trimesh.load('exports/model.hanger.bb97b27d.stl')
def top_at(x, z):
    o = np.array([[float(x), 60.0, float(z)]])
    d = np.array([[0.0, -1.0, 0.0]])
    loc, _, _ = h.ray.intersects_location(o, d, multiple_hits=True)
    return max((p[1] for p in loc), default=-1.0)
print('crown profile along X at Z=17 (centre):')
for x in [0, 15, 30, 45, 60]:
    print(f'  x={x}: y_top={top_at(x, 17):.2f}')
print('transverse section at x=30 (Z: y_top):')
for z in [0.5, 5, 10, 17, 24, 29, 33.5]:
    print(f'  z={z}: y_top={top_at(30, z):.2f}')
print('transverse section at x=0:')
for z in [0.5, 2, 3, 5, 17, 29, 31, 33.5]:
    print(f'  z={z}: y_top={top_at(0, z):.2f}')
